  35|// Reconcile audits the project for state inconsistencies and corrects them.
  36|// It is called periodically from doTick and can also be invoked on demand
  37|// from the TUI. Returns the number of fixes applied.
  38|func (o *Orchestrator) Reconcile() (int, error) {
  39|	var r ReconcileResult
  40|
  41|	if n, err := o.reconcileStaleSubtasks(); err != nil {
  42|		return 0, fmt.Errorf("reconcile stale subtasks: %w", err)
  43|	} else {
  44|		r.StaleSubtasksReset = n
  45|	}
  46|
  47|	if n, err := o.reconcileOrphanedSubtasks(); err != nil {
  48|		return 0, fmt.Errorf("reconcile orphaned subtasks: %w", err)
  49|	} else {
  50|		r.OrphanedSubtasksFixed = n
  51|	}
  52|
  53|	if n, err := o.reconcileEmptyFeatures(); err != nil {
  54|		return 0, fmt.Errorf("reconcile empty features: %w", err)
  55|	} else {
  56|		r.EmptyFeaturesFailed = n
  57|	}
  58|
  59|	if n, err := o.reconcileOrphanWorktrees(); err != nil {
  60|		return 0, fmt.Errorf("reconcile orphan worktrees: %w", err)
  61|	} else {
  62|		r.OrphanWorktreesCleaned = n
  63|	}
  64|
  65|	if n, err := o.reconcileStuckAgents(); err != nil {
  66|		return 0, fmt.Errorf("reconcile stuck agents: %w", err)
  67|	} else {
  68|		r.StuckAgentsRecovered = n
  69|	}
  70|
  71|	if n, err := o.reconcileOrphanedTaskAssignments(); err != nil {
  72|		return 0, fmt.Errorf("reconcile orphaned task assignments: %w", err)
  73|	} else {
  74|		r.OrphanedAssignmentsCleared = n
  75|	}
  76|
  77|	if n, err := o.reconcileAlreadyMergedFeatures(); err != nil {
  78|		return 0, fmt.Errorf("reconcile already-merged features: %w", err)
  79|	} else {
  80|		r.AlreadyMergedFeaturesFixed = n
  81|	}
  82|
  83|	if n, err := o.reconcileCompletedParents(); err != nil {
  84|		return 0, fmt.Errorf("reconcile completed parents: %w", err)
  85|	} else {
  86|		r.CompletedParentsAdvanced = n
  87|	}
  88|
  89|	if n, err := o.reconcileFailedParents(); err != nil {
  90|		return 0, fmt.Errorf("reconcile failed parents: %w", err)
  91|	} else {
  92|		r.FailedParentsRecovered = n
  93|	}
  94|
  95|	total := r.StaleSubtasksReset + r.OrphanedSubtasksFixed + r.EmptyFeaturesFailed + r.OrphanWorktreesCleaned + r.StuckAgentsRecovered + r.OrphanedAssignmentsCleared + r.AlreadyMergedFeaturesFixed + r.CompletedParentsAdvanced + r.FailedParentsRecovered
  96|	if total > 0 {
  97|		o.emit("reconcile", r)
  98|	}
  99|	return total, nil
