 102|// reconcileStaleSubtasks finds subtasks marked DONE whose parent is still
 103|// IN_PROGRESS and verifies the subtask's agent actually contributed commits
 104|// to the feature branch. Subtasks that are DONE but have no corresponding
 105|// work are reset to BACKLOG for rescheduling.
 106|func (o *Orchestrator) reconcileStaleSubtasks() (int, error) {
 107|	// Find IN_PROGRESS parents with at least one DONE subtask.
 108|	var parents []model.Task
 109|	if err := o.db.Where(
 110|		"project_id = ? AND status = ? AND parent_task_id IS NULL",
 111|		o.projectID, model.StatusInProgress,
 112|	).Find(&parents).Error; err != nil {
 113|		return 0, err
 114|	}
 115|
 116|	fixed := 0
 117|	for _, parent := range parents {
 118|		if parent.WorktreeBranch == "" {
 119|			continue
 120|		}
 121|
 122|		var subs []model.Task
 123|		if err := o.db.Where("parent_task_id = ? AND status = ?", parent.ID, model.StatusDone).
 124|			Find(&subs).Error; err != nil {
 125|			continue
 126|		}
 127|
 128|		fn := strings.TrimPrefix(parent.WorktreeBranch, "feature/")
 129|		featureDir := o.worktree.FeatureWorktreePath(fn)
 130|
 131|		// Get the set of files changed on the feature branch. If empty,
 132|		// every DONE subtask is suspect.
 133|		changedFiles, err := worktree.GetChangedFiles(featureDir, o.worktree.DefaultBranch)
 134|		if err != nil {
 135|			continue
 136|		}
 137|		if len(changedFiles) > 0 {
 138|			// Feature branch has changes — subtasks plausibly contributed.
 139|			continue
 140|		}
 141|
 142|		// Feature branch has no changes but subtasks claim to be done.
 143|		for i := range subs {
 144|			sub := &subs[i]
 145|			o.logger.Warn("reconcile: resetting done subtask with no feature changes",
 146|				"subtask_id", sub.ID, "parent_id", parent.ID)
 147|
 148|			// Force status back to backlog (bypasses state machine since
 149|			// DONE is terminal and has no valid outbound transitions).
 150|			sub.Status = model.StatusBacklog
 151|			sub.AssignedAgentID = nil
 152|			sub.UpdatedAt = time.Now()
 153|			if sub.Context == nil {
 154|				sub.Context = make(model.JSONField)
 155|			}
 156|			sub.Context["reconciled"] = true
 157|			sub.Context["reconcile_reason"] = "subtask was done but feature branch has no changes"
 158|			if err := o.db.Save(sub).Error; err != nil {
 159|				o.logger.Error("reconcile: save subtask", "subtask_id", sub.ID, "error", err)
 160|				continue
 161|			}
 162|			fixed++
 163|		}
 164|	}
 165|	return fixed, nil
 166|}
