 168|// reconcileOrphanedSubtasks finds IN_PROGRESS subtasks whose assigned agent
 169|// is idle or dead — meaning the agent finished but the completion signal was
 170|// lost before the subtask could be transitioned. For each orphaned subtask,
 171|// it attempts to merge any remaining agent work into the feature branch and
 172|// transitions the subtask to TESTING_READY so the normal quality gate can
 173|// verify build and test correctness. If the agent branch has no mergeable
 174|// work and the feature branch is empty, the subtask is reset to BACKLOG.
 175|func (o *Orchestrator) reconcileOrphanedSubtasks() (int, error) {
 176|	var subtasks []model.Task
 177|	if err := o.db.Where(
 178|		"project_id = ? AND status = ? AND parent_task_id IS NOT NULL AND assigned_agent_id IS NOT NULL",
 179|		o.projectID, model.StatusInProgress,
 180|	).Find(&subtasks).Error; err != nil {
 181|		return 0, err
 182|	}
 183|
 184|	fixed := 0
 185|	for i := range subtasks {
 186|		sub := &subtasks[i]
 187|
 188|		var ag model.Agent
 189|		if err := o.db.First(&ag, "id = ?", sub.AssignedAgentID).Error; err != nil {
 190|			// Agent record missing — reset subtask for rescheduling.
 191|			o.logger.Warn("reconcile: assigned agent not found, resetting subtask",
 192|				"subtask_id", sub.ID, "agent_id", sub.AssignedAgentID)
 193|			sub.Status = model.StatusBacklog
 194|			sub.AssignedAgentID = nil
 195|			sub.UpdatedAt = time.Now()
 196|			if err := o.db.Save(sub).Error; err != nil {
 197|				o.logger.Error("reconcile: save subtask", "subtask_id", sub.ID, "error", err)
 198|			}
 199|			fixed++
 200|			continue
