 201|		}
 202|
 203|		// Only act if the agent is no longer actively working.
 204|		if ag.Status == model.AgentWorking || ag.Status == model.AgentBlocked {
 205|			continue
 206|		}
 207|
 208|		o.logger.Info("reconcile: processing orphaned in_progress subtask",
 209|			"subtask_id", sub.ID, "agent_id", ag.ID, "agent_status", ag.Status)
 210|
 211|		// Resolve the feature branch from the parent task.
 212|		featureBranch := ""
 213|		if sub.ParentTaskID != nil {
 214|			var parent model.Task
 215|			if err := o.db.Select("worktree_branch").First(&parent, "id = ?", sub.ParentTaskID).Error; err == nil {
 216|				featureBranch = parent.WorktreeBranch
 217|			}
 218|		}
 219|
 220|		// Before resetting, check if work is already merged.
 221|		if featureBranch != "" {
 222|			fn := strings.TrimPrefix(featureBranch, "feature/")
 223|			featureDir := o.worktree.FeatureWorktreePath(fn)
 224|			if o.isWorkAlreadyMerged(sub, featureDir) {
 225|				o.logger.Info("reconcile: work already merged, transitioning to quality gate",
 226|					"subtask_id", sub.ID, "agent_id", ag.ID)
 227|				// Fast-track subtask to done (matches onAgentCompleted / scheduleSubtasks).
 228|				transitions := []model.TaskStatus{
 229|					model.StatusTestingReady,
 230|					model.StatusMerging,
 231|					model.StatusDone,
 232|				}
 233|				for _, target := range transitions {
 234|					if sub.Status == target {
 235|						continue
 236|					}
 237|					evt, tErr := state.TransitionTask(sub, target, "orchestrator",
 238|						map[string]any{"reason": "reconcile-already-merged"})
 239|					if tErr != nil {
 240|						continue
 241|					}
 242|					if err := o.db.Create(evt).Error; err != nil {
 243|						o.logger.Error("reconcile: save event", "subtask_id", sub.ID, "error", err)
 244|						break
 245|					}
 246|				}
 247|				if err := o.db.Save(sub).Error; err != nil {
 248|					o.logger.Error("reconcile: save subtask", "subtask_id", sub.ID, "error", err)
 249|				}
 250|				// Clean up agent worktree since work is merged.
 251|				if ag.WorktreeBranch != "" {
 252|					if err := o.worktree.RemoveAgentWorktree(ag.WorktreeBranch); err != nil {
 253|						o.logger.Warn("reconcile: cleanup agent worktree", "agent_id", ag.ID, "error", err)
 254|					}
 255|				}
 256|				fixed++
 257|				continue
 258|			}
 259|		}
 260|
 261|		// Attempt to merge agent work if the branch still exists.
 262|		merged := false
 263|		if ag.WorktreeBranch != "" && featureBranch != "" {
 264|			fn := strings.TrimPrefix(featureBranch, "feature/")
 265|			featureDir := o.worktree.FeatureWorktreePath(fn)
 266|
 267|			// Ensure the feature worktree is clean before merge attempts.
 268|			// Leftover changes (e.g. plan.json) block MergeAgentIntoFeature.
 269|			if committed, cErr := worktree.CommitUnstagedChanges(
 270|				featureDir, "Auto-commit uncommitted feature worktree changes (reconcile)",
 271|			); cErr != nil {
 272|				o.logger.Warn("reconcile: failed to clean feature worktree", "feature", featureBranch, "error", cErr)
 273|			} else if committed {
 274|				o.logger.Info("reconcile: committed leftover changes in feature worktree", "feature", featureBranch)
 275|			}
 276|
 277|			hasCommits, err := worktree.BranchHasNewCommits(featureDir, ag.WorktreeBranch)
 278|			if err != nil {
 279|				// Branch likely already cleaned up — assume merge happened.
 280|				merged = true
 281|			} else if hasCommits {
 282|				result, mergeErr := o.merger.MergeAgentIntoFeature(ag.WorktreeBranch, featureDir)
 283|				if mergeErr != nil {
 284|					o.logger.Error("reconcile: merge agent into feature failed",
 285|						"subtask_id", sub.ID, "agent_id", ag.ID, "error", mergeErr)
 286|				} else if result.Success {
 287|					merged = true
 288|					if err := o.worktree.RemoveAgentWorktree(ag.WorktreeBranch); err != nil {
 289|						o.logger.Warn("reconcile: cleanup agent worktree", "agent_id", ag.ID, "error", err)
 290|					}
 291|				} else {
 292|					o.logger.Error("reconcile: merge had conflicts",
 293|						"subtask_id", sub.ID, "conflicts", result.Conflicts)
 294|				}
 295|			} else {
 296|				// No commits on agent branch — already merged or empty work.
 297|				merged = true
 298|			}
 299|		} else {
 300|			merged = true
 301|		}
 302|
 303|		if !merged {
 304|			// Merge failed — keep the agent worktree/branch intact so work
 305|			// is not lost (consistent with onAgentCompleted behavior).
 306|			if err := o.failTask(sub, "reconcile: agent work could not be merged into feature branch (agent branch preserved)"); err != nil {
 307|				o.logger.Error("reconcile: fail subtask", "subtask_id", sub.ID, "error", err)
 308|			}
 309|			// Leave agent worktree intact for manual resolution or retry.
 310|			fixed++
 311|			continue
 312|		}
 313|
 314|		// Clean up the agent record if it still references this subtask.
 315|		if ag.CurrentTaskID != nil && *ag.CurrentTaskID == sub.ID {
 316|			ag.CurrentTaskID = nil
 317|			if ag.Status == model.AgentDead {
 318|				ag.Status = model.AgentIdle
 319|			}
 320|			if err := o.db.Save(&ag).Error; err != nil {
 321|				o.logger.Error("reconcile: save agent", "agent_id", ag.ID, "error", err)
 322|			}
 323|		}
 324|
 325|		// Fast-track subtask to done (matches onAgentCompleted / scheduleSubtasks).
 326|		transitions := []model.TaskStatus{
 327|			model.StatusTestingReady,
 328|			model.StatusMerging,
 329|			model.StatusDone,
 330|		}
 331|		for _, target := range transitions {
 332|			if sub.Status == target {
 333|				continue
 334|			}
 335|			evt, err := state.TransitionTask(sub, target, "orchestrator",
 336|				map[string]any{"reason": "reconcile-merged"})
 337|			if err != nil {
 338|				o.logger.Debug("reconcile transition skip",
 339|					"subtask_id", sub.ID, "from", sub.Status, "to", target, "error", err)
 340|				continue
 341|			}
 342|			if err := o.db.Create(evt).Error; err != nil {
 343|				o.logger.Error("reconcile: save event", "subtask_id", sub.ID, "error", err)
 344|				break
 345|			}
 346|		}
 347|
 348|		if err := o.db.Save(sub).Error; err != nil {
 349|			o.logger.Error("reconcile: save subtask", "subtask_id", sub.ID, "error", err)
 350|			continue
 351|		}
 352|		fixed++
 353|	}
 354|	return fixed, nil
