 402|// reconcileOrphanWorktrees finds agent worktrees in each feature directory
 403|// that have no commits ahead of the feature branch and no corresponding
 404|// WORKING agent in the database, and removes them.
 405|func (o *Orchestrator) reconcileOrphanWorktrees() (int, error) {
 406|	// Collect all WORKING agent branches.
 407|	var workingAgents []model.Agent
 408|	if err := o.db.Where("project_id = ? AND status = ?", o.projectID, model.AgentWorking).
 409|		Find(&workingAgents).Error; err != nil {
 410|		return 0, err
 411|	}
 412|	activeBranches := make(map[string]bool, len(workingAgents))
 413|	for _, ag := range workingAgents {
 414|		activeBranches[ag.WorktreeBranch] = true
 415|	}
 416|
 417|	// Find all feature parents to scan their worktree directories.
 418|	var parents []model.Task
 419|	if err := o.db.Where(
 420|		"project_id = ? AND parent_task_id IS NULL AND worktree_branch != ''",
 421|		o.projectID,
 422|	).Find(&parents).Error; err != nil {
 423|		return 0, err
 424|	}
 425|
 426|	cleaned := 0
 427|	for _, parent := range parents {
 428|		fn := strings.TrimPrefix(parent.WorktreeBranch, "feature/")
 429|		featureDir := o.worktree.FeatureWorktreePath(fn)
 430|
 431|		agentWorktrees, err := o.worktree.ListAgentWorktrees(fn)
 432|		if err != nil {
 433|			continue
 434|		}
 435|
 436|		for _, awt := range agentWorktrees {
 437|			if !strings.HasPrefix(awt.Branch, "worktree-agent-") {
 438|				o.logger.Warn("reconcile: skipping non-agent branch in orphan cleanup",
 439|					"branch", awt.Branch, "feature", parent.WorktreeBranch)
 440|				continue
 441|			}
 442|
 443|			if activeBranches[awt.Branch] {
 444|				continue // agent is actively working
 445|			}
 446|
 447|			// Check if the worktree has commits.
 448|			hasCommits, err := worktree.BranchHasNewCommits(featureDir, awt.Branch)
 449|			if err != nil {
 450|				continue
 451|			}
 452|			if hasCommits {
 453|				continue // has real work, leave it
 454|			}
 455|
 456|			o.logger.Info("reconcile: removing orphan empty worktree",
 457|				"branch", awt.Branch, "feature", parent.WorktreeBranch)
 458|			if err := o.worktree.RemoveAgentWorktree(awt.Branch); err != nil {
 459|				o.logger.Warn("reconcile: remove orphan worktree", "branch", awt.Branch, "error", err)
 460|				continue
 461|			}
 462|			cleaned++
 463|		}
 464|	}
 465|	return cleaned, nil
 466|}
