 468|// reconcileStuckAgents finds tasks in actionable statuses (classifying,
 469|// planning, test_writing, in_progress) whose assigned agent's tmux session
 470|// is dead but no completion was ever received. This catches agents that
 471|// exited without triggering the monitor goroutine. Covers both top-level
 472|// tasks and subtasks.
 473|func (o *Orchestrator) reconcileStuckAgents() (int, error) {
 474|	var tasks []model.Task
 475|	if err := o.db.Where(
 476|		"project_id = ? AND status IN ? AND assigned_agent_id IS NOT NULL",
 477|		o.projectID, []model.TaskStatus{model.StatusClassifying, model.StatusPlanning, model.StatusTestWriting, model.StatusInProgress},
 478|	).Find(&tasks).Error; err != nil {
 479|		return 0, err
 480|	}
 481|
 482|	// Build a set of agent IDs that the runner considers active.
 483|	runningAgents := o.runner.GetRunningAgents()
 484|	runningSet := make(map[uuid.UUID]bool, len(runningAgents))
 485|	for _, ra := range runningAgents {
 486|		runningSet[ra.AgentID] = true
 487|	}
 488|
 489|	fixed := 0
 490|	for i := range tasks {
 491|		task := &tasks[i]
 492|
 493|		var ag model.Agent
 494|		if err := o.db.First(&ag, "id = ?", task.AssignedAgentID).Error; err != nil {
 495|			continue
 496|		}
 497|
 498|		// Only act on agents that are still marked as working in the DB.
 499|		if ag.Status != model.AgentWorking {
 500|			continue
 501|		}
 502|
 503|		// Skip agents that the runner still considers active.
 504|		if runningSet[ag.ID] {
 505|			continue
 506|		}
 507|
 508|		// Grace period: skip agents that were recently spawned. This prevents
 509|		// false positives when an agent's process hasn't been fully registered
 510|		// in the runner's running map yet.
 511|		if ag.CreatedAt.After(time.Now().Add(-agentSpawnGracePeriod)) {
 512|			continue
 513|		}
 514|
 515|		// Agent is NOT in the runner's running map AND DB status is working.
 516|		o.logger.Warn("detected dead agent session without completion",
 517|			"agent_id", ag.ID, "task", task.Title, "session", ag.TmuxSession)
 518|
 519|		// Check if the agent branch has commits.
 520|		featureDir := o.resolveFeatureWorktree(task)
 521|		hasCommits := false
 522|		if featureDir != "" && ag.WorktreeBranch != "" {
 523|			var err error
 524|			hasCommits, err = worktree.BranchHasNewCommits(featureDir, ag.WorktreeBranch)
 525|			if err != nil {
 526|				o.logger.Warn("reconcile stuck: failed to check commits",
 527|					"agent_id", ag.ID, "error", err)
 528|			}
 529|		}
 530|
 531|		if hasCommits {
 532|			// Route through the normal completion path.
 533|			o.logger.Info("reconcile stuck: agent has commits, sending completion",
 534|				"agent_id", ag.ID, "task", task.Title)
 535|			if err := o.synthesizeCompletion(ag.ID); err != nil {
 536|				o.logger.Error("reconcile stuck: process completion",
 537|					"agent_id", ag.ID, "error", err)
 538|			}
 539|		} else {
 540|			// No work produced — check if we can retry before failing.
 541|			ag.Status = model.AgentDead
 542|			ag.CurrentTaskID = nil
 543|			if err := o.db.Save(&ag).Error; err != nil {
 544|				o.logger.Error("reconcile stuck: save agent", "agent_id", ag.ID, "error", err)
 545|				continue
 546|			}
 547|			o.publishAgentStatus(task.ID.String(), ag.ID.String(), string(ag.AgentType), string(model.AgentDead))
 548|
 549|			// Auto-retry if under the limit. Use MaxPlannerRetries for
 550|			// PLANNING tasks (planner agents) since they have a different
 551|			// retry budget than generic empty-work retries.
 552|			retryCount := 0
